{
  "name": "rf_process_event",
  "confidence": "medium",
  "docstring": "Selects the next due RF event from a queued list, marks the radio as busy, updates the corresponding event-mode entry, and waits for the required radio state.",
  "subsystem": "rf",
  "var_renames": {
    "a2": "event_filter",
    "v2": "rf_busy_flag_ptr",
    "v3": "event_list_ptr",
    "v4": "due_event_count",
    "v5": "event_count_field_ptr",
    "v6": "event_node",
    "v7": "active_event_node",
    "v8": "event_timestamp",
    "v9": "scan_node",
    "v10": "scan_remaining",
    "v11": "scan_index",
    "v12": "radio_wait_arg",
    "v13": "event_mode_entry",
    "v14": "event_mode_bits"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "intrusive list next pointer for event/scan nodes"
    },
    {
      "offset": 4,
      "meaning": "node field used either as the radio wait parameter/event descriptor or as the event-mode array base depending on context"
    },
    {
      "offset": 12,
      "meaning": "uint16 timestamp/sequence field used to order or test due events"
    },
    {
      "offset": 14,
      "meaning": "uint8 event-mode slot index used to address an 8-byte mode entry"
    },
    {
      "offset": 3,
      "meaning": "control byte within an event-mode entry whose low bits are updated"
    }
  ]
}
